struct Config {std::array<float,fields> v=defaults;};
inline bool discrete(int f){return f==type||f==color||f==seed||f==style||f==repeat;}
inline int index(const char* key){if(std::strncmp(key,"noise_",6))return -1;for(int f=0;f<fields;++f)if(!std::strcmp(key,keys[f]))return f;return -1;}
inline bool set(Config& c,int f,float x){if(f<0||f>=fields||!std::isfinite(x))return false;if(f>=ratios&&c.v[style]!=3){for(int j=0;j<32;++j)c.v[ratios+j]=c.v[style]==0?float(j+1):c.v[style]==1?float(2*j+1):1.f+1.41421356f*j;c.v[style]=3;}c.v[f]=std::clamp(discrete(f)?std::round(x):x,low[f],high[f]);return true;}
inline bool valid(const Config& c){for(int f=0;f<fields;++f)if(!std::isfinite(c.v[f])||c.v[f]<low[f]||c.v[f]>high[f]||(discrete(f)&&std::floor(c.v[f])!=c.v[f]))return false;return true;}
inline float resolved(const Config& c,int f){if(f>=ratios&&f<bands&&c.v[style]!=3){int j=f-ratios;return c.v[style]==0?float(j+1):c.v[style]==1?float(2*j+1):1.f+1.41421356f*j;}return c.v[f];}
inline bool applicable(const Config& c,int f){if(f<0||f>=fields)return false;const int t=int(c.v[type]);if((f>=count&&f<=style)||f>=ratios)return t==0;if(f>=rate&&f<=fault){if(t==0)return false;if(f==fault)return t==6;if(t==3)return f==rate||f==size||f==clump||f==variation;return true;}return true;}
struct Program {std::array<Config,4> patches{};Program(){patches[1].v[type]=1;patches[2].v[type]=2;patches[3].v[type]=3;}};
